// online all-to-all pair STDP
const dx = Math.exp(-dt / tauPlus), dy = Math.exp(-dt / tauMinus);
function stdpStep(preSpiked, postSpiked) {
  x *= dx; y *= dy;
  if (preSpiked)  { w -= aMinus * y; x += 1; }
  if (postSpiked) { w += aPlus  * x; y += 1; }
  w = Math.min(wMax, Math.max(0, w));
}
